const listWaitlistEntries = `-- name: ListWaitlistEntries :many
SELECT w.id, w.person_id, w.enrollment_id, w.property_id, w.room_type_id, w.check_in,
       w.check_out, w.adults, w.children, w.priority, w.status, w.offered_booking_id,
       w.offer_expires_at, w.created_at, w.updated_at, w.row_version
  FROM accommodation.waitlist_entry w
  JOIN accommodation.property p ON p.tenant_id = w.tenant_id AND p.id = w.property_id
 WHERE w.tenant_id = $1
   AND ($2::uuid IS NULL OR w.person_id = $2::uuid)
   AND ($3::uuid IS NULL OR w.property_id = $3::uuid)
   AND ($4::text IS NULL OR w.status = $4::text)
   AND ($5::uuid[] IS NULL
        OR p.provider_organization_id = ANY($5::uuid[]))
 ORDER BY w.priority DESC, w.created_at ASC, w.id ASC
 LIMIT $6
`

type ListWaitlistEntriesParams struct {
	TenantID   uuid.UUID
	PersonID   uuid.NullUUID
	PropertyID uuid.NullUUID
	Status     *string
	ScopeIds   []uuid.UUID
	PageSize   int32
}

type ListWaitlistEntriesRow struct {
	ID               uuid.UUID
	PersonID         uuid.UUID
	EnrollmentID     uuid.UUID
	PropertyID       uuid.UUID
	RoomTypeID       uuid.NullUUID
	CheckIn          pgtype.Date
	CheckOut         pgtype.Date
	Adults           int32
	Children         int32
	Priority         int32
	Status           string
	OfferedBookingID uuid.NullUUID
	OfferExpiresAt   *time.Time
	CreatedAt        time.Time
	UpdatedAt        time.Time
	RowVersion       int64
}

// The queue as a screen reads it, in the order the sweep walks it, so the list a member is
// shown their place in is the list the offer actually comes out of.
func (q *Queries) ListWaitlistEntries(ctx context.Context, arg ListWaitlistEntriesParams) ([]ListWaitlistEntriesRow, error) {
	rows, err := q.db.Query(ctx, listWaitlistEntries,
		arg.TenantID,
		arg.PersonID,
		arg.PropertyID,
		arg.Status,
		arg.ScopeIds,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWaitlistEntriesRow
	for rows.Next() {
		var i ListWaitlistEntriesRow
		if err := rows.Scan(
			&i.ID,
			&i.PersonID,
			&i.EnrollmentID,
			&i.PropertyID,
			&i.RoomTypeID,
			&i.CheckIn,
			&i.CheckOut,
			&i.Adults,
			&i.Children,
			&i.Priority,
			&i.Status,
			&i.OfferedBookingID,
			&i.OfferExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RowVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listWaitlistQueue = `-- name: ListWaitlistQueue :many
SELECT id, person_id, enrollment_id, property_id, room_type_id, check_in, check_out,
       adults, children, priority, status, offered_booking_id, offer_expires_at,
       created_at, updated_at, row_version
  FROM accommodation.waitlist_entry
 WHERE tenant_id = $1
   AND status = 'WAITING'
 ORDER BY priority DESC, created_at ASC, id ASC
 LIMIT $2
   FOR UPDATE SKIP LOCKED
`

type ListWaitlistQueueParams struct {
	TenantID uuid.UUID
	PageSize int32
}

type ListWaitlistQueueRow struct {
	ID               uuid.UUID
	PersonID         uuid.UUID
	EnrollmentID     uuid.UUID
	PropertyID       uuid.UUID
	RoomTypeID       uuid.NullUUID
	CheckIn          pgtype.Date
	CheckOut         pgtype.Date
	Adults           int32
	Children         int32
	Priority         int32
	Status           string
	OfferedBookingID uuid.NullUUID
	OfferExpiresAt   *time.Time
	CreatedAt        time.Time
	UpdatedAt        time.Time
	RowVersion       int64
}

// The sweep's own read: the WAITING entries of one tenant, highest priority first and then
// whoever asked first, taken FOR UPDATE SKIP LOCKED so two schedulers that both believe
// they lead take different entries and neither waits on the other.
//
// The ORDER BY is spelled exactly as `ix_waitlist_queue` is. A sweep that ordered by
// `created_at` alone would be a plan clause nobody honoured, and the test that proves
// priority wins is the one that would go red.
func (q *Queries) ListWaitlistQueue(ctx context.Context, arg ListWaitlistQueueParams) ([]ListWaitlistQueueRow, error) {
	rows, err := q.db.Query(ctx, listWaitlistQueue, arg.TenantID, arg.PageSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWaitlistQueueRow
	for rows.Next() {
		var i ListWaitlistQueueRow
		if err := rows.Scan(
			&i.ID,
			&i.PersonID,
			&i.EnrollmentID,
			&i.PropertyID,
			&i.RoomTypeID,
			&i.CheckIn,
			&i.CheckOut,
			&i.Adults,
			&i.Children,
			&i.Priority,
			&i.Status,
			&i.OfferedBookingID,
			&i.OfferExpiresAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RowVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockNoShow = `-- name: LockNoShow :one
SELECT id, booking_id, reported_by_actor_id, reported_at, evidence_document_id,
       assessed_fee_amount::text AS assessed_fee_amount, payer_amount::text AS payer_amount,
       member_amount::text AS member_amount, currency_code, status, reviewed_by,
       reviewed_at, review_comment, consumed_nights, created_at, updated_at, row_version
  FROM accommodation.no_show
 WHERE tenant_id = $1
   AND id = $2
   FOR UPDATE
`

type LockNoShowParams struct {
	TenantID uuid.UUID
	ID       uuid.UUID
}

type LockNoShowRow struct {
	ID                 uuid.UUID
	BookingID          uuid.UUID
	ReportedByActorID  uuid.NullUUID
	ReportedAt         time.Time
	EvidenceDocumentID uuid.NullUUID
	AssessedFeeAmount  string
	PayerAmount        string
	MemberAmount       string
	CurrencyCode       string
	Status             string
	ReviewedBy         uuid.NullUUID
	ReviewedAt         *time.Time
	ReviewComment      *string
	ConsumedNights     int32
	CreatedAt          time.Time
	UpdatedAt          time.Time
	RowVersion         int64
}

// The report FOR UPDATE, for the review that is about to decide it. The maker-checker rule
// is not in this WHERE: the reporter's actor id comes back with the row and the service
// compares it, so the refusal can say what it is instead of being an empty result.
func (q *Queries) LockNoShow(ctx context.Context, arg LockNoShowParams) (LockNoShowRow, error) {
	row := q.db.QueryRow(ctx, lockNoShow, arg.TenantID, arg.ID)
	var i LockNoShowRow
	err := row.Scan(
		&i.ID,
		&i.BookingID,
		&i.ReportedByActorID,
		&i.ReportedAt,
		&i.EvidenceDocumentID,
		&i.AssessedFeeAmount,
		&i.PayerAmount,
		&i.MemberAmount,
		&i.CurrencyCode,
		&i.Status,
		&i.ReviewedBy,
		&i.ReviewedAt,
		&i.ReviewComment,
		&i.ConsumedNights,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RowVersion,
	)
	return i, err
}

