const markBookingNoShow = `-- name: MarkBookingNoShow :execrows
UPDATE accommodation.booking
   SET status = 'NO_SHOW', cancel_reason_code = 'NO_SHOW', updated_by = $1
 WHERE tenant_id = $2
   AND id = $3
   AND status = 'CONFIRMED'
`

type MarkBookingNoShowParams struct {
	ActorID  uuid.NullUUID
	TenantID uuid.UUID
	ID       uuid.UUID
}

// The payer confirmed the provider's report. CONFIRMED only: a booking that was checked in
// cannot have been a no-show, and one already cancelled is not one either.
func (q *Queries) MarkBookingNoShow(ctx context.Context, arg MarkBookingNoShowParams) (int64, error) {
	result, err := q.db.Exec(ctx, markBookingNoShow, arg.ActorID, arg.TenantID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const offerWaitlistEntry = `-- name: OfferWaitlistEntry :execrows
UPDATE accommodation.waitlist_entry
   SET status = 'OFFERED', offered_booking_id = $1,
       offer_expires_at = $2
 WHERE tenant_id = $3
   AND id = $4
   AND status = 'WAITING'
`

type OfferWaitlistEntryParams struct {
	OfferedBookingID uuid.NullUUID
	OfferExpiresAt   *time.Time
	TenantID         uuid.UUID
	ID               uuid.UUID
}

// The room reached this entry. WAITING is the predicate, so a second sweep pass over an
// entry that has already been offered one changes nothing.
func (q *Queries) OfferWaitlistEntry(ctx context.Context, arg OfferWaitlistEntryParams) (int64, error) {
	result, err := q.db.Exec(ctx, offerWaitlistEntry,
		arg.OfferedBookingID,
		arg.OfferExpiresAt,
		arg.TenantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const returnWaitlistEntryToQueue = `-- name: ReturnWaitlistEntryToQueue :execrows
UPDATE accommodation.waitlist_entry
   SET status = 'WAITING', offered_booking_id = NULL, offer_expires_at = NULL,
       created_at = $1
 WHERE tenant_id = $2
   AND id = $3
   AND status = 'OFFERED'
`

type ReturnWaitlistEntryToQueueParams struct {
	RequeuedAt time.Time
	TenantID   uuid.UUID
	ID         uuid.UUID
}

// An offer nobody took. The entry goes back to WAITING *behind* everybody who was already
// queued, and that is what moving `created_at` to now does: the queue is ordered by it, so
// a member who let a room go waits again rather than being offered the next one first.
func (q *Queries) ReturnWaitlistEntryToQueue(ctx context.Context, arg ReturnWaitlistEntryToQueueParams) (int64, error) {
	result, err := q.db.Exec(ctx, returnWaitlistEntryToQueue, arg.RequeuedAt, arg.TenantID, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reviewNoShow = `-- name: ReviewNoShow :execrows
UPDATE accommodation.no_show
   SET status = $1, reviewed_by = $2,
       reviewed_at = $3, review_comment = $4,
       consumed_nights = $5::int, updated_by = $2
 WHERE tenant_id = $6
   AND id = $7
   AND status = 'REPORTED'
`

type ReviewNoShowParams struct {
	Status         string
	ReviewedBy     uuid.NullUUID
	ReviewedAt     *time.Time
	ReviewComment  *string
	ConsumedNights int32
	TenantID       uuid.UUID
	ID             uuid.UUID
}

// The payer's answer. The REPORTED predicate is the whole of its idempotency, and
// `reviewed_by <> reported_by_actor_id` is a CHECK on the row underneath the service's own
// refusal: the person who said nobody came may never be the person who decides it costs the
// member anything.
func (q *Queries) ReviewNoShow(ctx context.Context, arg ReviewNoShowParams) (int64, error) {
	result, err := q.db.Exec(ctx, reviewNoShow,
		arg.Status,
		arg.ReviewedBy,
		arg.ReviewedAt,
		arg.ReviewComment,
		arg.ConsumedNights,
		arg.TenantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
